SELECT dept_name, CASE WHEN budget >= 3844000 THEN 'high' WHEN budget >= 659000 THEN 'mid' ELSE 'low' END AS budget_bucket, SORT_ARRAY(COLLECT_SET(location)) AS location_list FROM departments GROUP BY dept_name, CASE WHEN budget >= 3844000 THEN 'high' WHEN budget >= 659000 THEN 'mid' ELSE 'low' END
